// Evaluation template: Conversation Summaries
//
// The actual summary TEXT is generated by an inline call to gpt-4o-mini
// inside bot/index.js, which (per TEST_AUDIT.md) cannot be imported in a
// test/eval process without triggering the WhatsApp bootstrap. So this
// suite evaluates the part that IS safely reusable: the storage/shape
// contract in bot/services/memory.service.js that every summary — real or
// fixture — must satisfy, using a fake Firestore (mock.module) so no real
// database is touched. Run with: node --experimental-test-module-mocks.
//
// TO EVALUATE LIVE SUMMARY QUALITY: point `fixtureSummarizer` below at the
// real prompt used in bot/index.js's maybeCreateConversationSummary (search
// CONVERSATION_SUMMARY_MODEL) with a real OpenAI client, keeping the
// judge()s in this file — they check structural quality, not wording.
import { mock } from "node:test";
import { runEvaluationSuite } from "../lib/evaluation-runner.js";

function createFakeFirestore() {
  const store = new Map();
  return {
    collection: () => ({
      doc: (id) => ({
        create: async (payload) => {
          if (store.has(`summary/${id}`)) throw new Error("doc already exists");
          store.set(`summary/${id}`, payload);
          return payload;
        },
      }),
      where: () => chain(),
      orderBy: () => chain(),
    }),
  };

  function chain() {
    return {
      where: () => chain(),
      orderBy: () => chain(),
      limit: () => chain(),
      get: async () => ({ empty: store.size === 0, docs: [] }),
    };
  }
}

mock.module("../../bot/firebase-admin.js", {
  namedExports: { db: createFakeFirestore(), bucket: {} },
});

const { saveConversationSummary } = await import("../../bot/services/memory.service.js");

// Stands in for the real LLM summarizer. Swap for a real OpenAI call (see
// header comment) to evaluate actual summary wording quality live.
function fixtureSummarizer(messages) {
  const topics = messages.map((m) => m.content).join(" ");
  const summary = `המשתמשת שוחחה על: ${topics}`.slice(0, 600);
  return { summary, messageCount: messages.length };
}

const cases = [
  {
    name: "a generated summary is never empty for a non-empty conversation",
    run: () => {
      const { summary, messageCount } = fixtureSummarizer([
        { role: "user", content: "אני מנסה לאכול יותר חלבון" },
        { role: "assistant", content: "אפשר להוסיף קטניות וביצים" },
      ]);
      return { summary, messageCount };
    },
    judge: ({ summary }) => ({
      verdict: summary.trim().length > 0 ? "PASS" : "FAIL",
      score: summary.trim().length > 0 ? 1 : 0,
      notes: summary.trim().length > 0 ? "Non-empty summary produced." : "Summary was empty for a real conversation.",
    }),
  },
  {
    name: "summary text stays within a sane length bound (not an unbounded transcript dump)",
    run: () => {
      const longMessages = Array.from({ length: 30 }, (_, i) => ({
        role: i % 2 === 0 ? "user" : "assistant",
        content: `הודעה מספר ${i} עם תוכן ארוך יחסית כדי לבדוק גבולות אורך`,
      }));
      return fixtureSummarizer(longMessages);
    },
    judge: ({ summary }) => {
      const withinBound = summary.length <= 600;
      return {
        verdict: withinBound ? "PASS" : "FAIL",
        score: withinBound ? 1 : 0,
        notes: `Summary length ${summary.length} chars (bound: 600).`,
      };
    },
  },
  {
    name: "saveConversationSummary persists with the documented default model/version and required fields",
    mode: "fixture",
    run: () => saveConversationSummary("user-eval-1", { summary: "המשתמשת מעדיפה ארוחות צמחוניות.", messageCount: 4 }),
    judge: (saved) => {
      const ok =
        saved.model === "gpt-4o-mini" &&
        saved.version === 1 &&
        saved.userId === "user-eval-1" &&
        typeof saved.summary === "string" &&
        saved.summary.length > 0;
      return {
        verdict: ok ? "PASS" : "FAIL",
        score: ok ? 1 : 0,
        notes: ok
          ? "Saved summary document has the documented shape (model, version, userId, summary)."
          : `Unexpected saved shape: ${JSON.stringify(saved)}`,
      };
    },
  },
  {
    name: "saveConversationSummary rejects an empty summary instead of writing a blank record",
    run: async () => {
      try {
        await saveConversationSummary("user-eval-2", { summary: "" });
        return { threw: false };
      } catch (error) {
        return { threw: true, message: error.message };
      }
    },
    judge: (result) => ({
      verdict: result.threw ? "PASS" : "FAIL",
      score: result.threw ? 1 : 0,
      notes: result.threw
        ? "Empty summary correctly rejected before any write."
        : "An empty summary was accepted and would have been persisted.",
    }),
  },
];

export async function runSuite() {
  return runEvaluationSuite("Conversation Summaries", cases);
}
